#!/usr/bin/env python3
"""
Miller - Simplified implementation in Python
Handles CSV, TSV, JSON, DKVP, and PPRINT formats
with basic verbs like cat, cut, sort, filter, put, stats1, etc.
"""

import sys
import argparse
import csv
import json
import re
from collections import OrderedDict, defaultdict
from typing import List, Dict, Any, Iterator
import io

def parse_args():
    parser = argparse.ArgumentParser(
        prog='mlr',
        description='Miller - data format conversion and processing'
    )

    # Input/Output format flags
    parser.add_argument('--csv', action='store_true', help='Input and output CSV')
    parser.add_argument('--icsv', action='store_true', help='Input CSV')
    parser.add_argument('--ocsv', action='store_true', help='Output CSV')

    parser.add_argument('--tsv', action='store_true', help='Input and output TSV')
    parser.add_argument('--itsv', action='store_true', help='Input TSV')
    parser.add_argument('--otsv', action='store_true', help='Output TSV')

    parser.add_argument('--dkvp', action='store_true', help='Input and output DKVP')
    parser.add_argument('--idkvp', action='store_true', help='Input DKVP')
    parser.add_argument('--odkvp', action='store_true', help='Output DKVP')

    parser.add_argument('--json', action='store_true', help='Input and output JSON')
    parser.add_argument('--ijson', action='store_true', help='Input JSON')
    parser.add_argument('--ojson', action='store_true', help='Output JSON')

    parser.add_argument('--pprint', action='store_true', help='Input and output PPRINT')
    parser.add_argument('--ipprint', action='store_true', help='Input PPRINT')
    parser.add_argument('--opprint', action='store_true', help='Output PPRINT')

    # Other flags
    parser.add_argument('--from', dest='from_file', help='Input file')
    parser.add_argument('-f', '--file', help='Input file (alternative)')

    parser.add_argument('verb', nargs='?', help='Miller verb to execute')
    parser.add_argument('verb_args', nargs=argparse.REMAINDER, help='Arguments for verb')

    return parser.parse_args()

def guess_input_format(args):
    if args.csv or args.icsv:
        return 'csv'
    if args.tsv or args.itsv:
        return 'tsv'
    if args.dkvp or args.idkvp:
        return 'dkvp'
    if args.json or args.ijson:
        return 'json'
    if args.pprint or args.ipprint:
        return 'pprint'
    return 'dkvp'  # Default

def guess_output_format(args):
    if args.csv or args.ocsv:
        return 'csv'
    if args.tsv or args.otsv:
        return 'tsv'
    if args.dkvp or args.odkvp:
        return 'dkvp'
    if args.json or args.ojson:
        return 'json'
    if args.pprint or args.opprint:
        return 'pprint'
    return 'dkvp'  # Default

def parse_dkvp_record(line: str) -> Dict[str, str]:
    """Parse a DKVP (key-value pair) record."""
    record = OrderedDict()
    pairs = line.split(',')
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            record[key] = value
    return record

def read_csv_records(file_handle) -> Iterator[Dict[str, str]]:
    """Read CSV records."""
    reader = csv.DictReader(file_handle)
    for row in reader:
        yield OrderedDict(row)

def read_dkvp_records(file_handle) -> Iterator[Dict[str, str]]:
    """Read DKVP records."""
    for line in file_handle:
        line = line.rstrip('\n\r')
        if line:
            yield parse_dkvp_record(line)

def read_json_records(file_handle) -> Iterator[Dict[str, str]]:
    """Read JSON lines records."""
    for line in file_handle:
        line = line.strip()
        if line:
            yield OrderedDict(json.loads(line))

def read_records(file_handle, fmt: str) -> Iterator[Dict[str, str]]:
    """Read records in specified format."""
    if fmt == 'csv':
        yield from read_csv_records(file_handle)
    elif fmt == 'tsv':
        # TSV is CSV with tab delimiter
        reader = csv.DictReader(file_handle, delimiter='\t')
        for row in reader:
            yield OrderedDict(row)
    elif fmt == 'dkvp':
        yield from read_dkvp_records(file_handle)
    elif fmt == 'json':
        yield from read_json_records(file_handle)

def write_dkvp_record(record: Dict[str, str]) -> str:
    """Write a DKVP record."""
    pairs = [f"{k}={v}" for k, v in record.items()]
    return ','.join(pairs)

def write_csv_record(record: Dict[str, str], writer) -> None:
    """Write a CSV record."""
    writer.writerow(record)

def write_json_record(record: Dict[str, str]) -> str:
    """Write a JSON record."""
    return json.dumps(record)

def write_records(records: Iterator[Dict[str, str]], fmt: str, file_handle) -> None:
    """Write records in specified format."""
    if fmt == 'csv':
        # Need to collect to get headers
        record_list = list(records)
        if not record_list:
            return
        writer = csv.DictWriter(file_handle, fieldnames=record_list[0].keys())
        writer.writeheader()
        for record in record_list:
            writer.writerow(record)
    elif fmt == 'tsv':
        record_list = list(records)
        if not record_list:
            return
        writer = csv.DictWriter(file_handle, fieldnames=record_list[0].keys(), delimiter='\t')
        writer.writeheader()
        for record in record_list:
            writer.writerow(record)
    elif fmt == 'dkvp':
        for record in records:
            file_handle.write(write_dkvp_record(record) + '\n')
    elif fmt == 'json':
        for record in records:
            file_handle.write(write_json_record(record) + '\n')

# Verb implementations
def verb_cat(records, args):
    """Pass through records."""
    return records

def verb_cut(records, args):
    """Select fields."""
    # Parse -f fields_list
    if '-f' not in args:
        return records

    idx = args.index('-f')
    fields_str = args[idx + 1]
    fields = fields_str.split(',')

    for record in records:
        new_record = OrderedDict()
        for field in fields:
            if field in record:
                new_record[field] = record[field]
        yield new_record

def verb_sort(records, args):
    """Sort records by field."""
    records_list = list(records)

    sort_field = None
    reverse = False
    numeric = False

    i = 0
    while i < len(args):
        if args[i] == '-f':
            sort_field = args[i + 1]
            i += 2
        elif args[i] == '-r':
            reverse = True
            i += 1
        elif args[i] == '-n':
            numeric = True
            i += 1
        elif args[i] == '-nr':
            numeric = True
            reverse = True
            i += 1
        else:
            i += 1

    if not sort_field:
        return records_list

    def sort_key(record):
        val = record.get(sort_field, '')
        if numeric:
            try:
                return float(val)
            except (ValueError, TypeError):
                return 0
        return val

    return sorted(records_list, key=sort_key, reverse=reverse)

def main():
    args = parse_args()

    # Handle help commands
    if args.verb == 'help' or args.verb is None:
        print_help()
        return

    # Get input/output formats
    input_fmt = guess_input_format(args)
    output_fmt = guess_output_format(args)

    # Get input file
    input_file = args.from_file or args.file or None
    if input_file:
        file_handle = open(input_file, 'r')
    else:
        file_handle = sys.stdin

    # Read records
    records = read_records(file_handle, input_fmt)

    # Apply verb
    if args.verb == 'cat':
        result = verb_cat(records, args.verb_args)
    elif args.verb == 'cut':
        result = verb_cut(records, args.verb_args)
    elif args.verb == 'sort':
        result = verb_sort(records, args.verb_args)
    else:
        result = records

    # Write records
    write_records(result, output_fmt, sys.stdout)

    if input_file:
        file_handle.close()

def print_help():
    print("""Usage: mlr [flags] {verb} [verb-dependent options ...] {zero or more file names}

If zero file names are provided, standard input is read, e.g.
  mlr --csv sort -f shape example.csv

Output of one verb may be chained as input to another using "then", e.g.
  mlr --csv stats1 -a min,mean,max -f quantity then sort -f color example.csv

Please see 'mlr help topics' for more information.
Please also see https://miller.readthedocs.io""")

if __name__ == '__main__':
    main()
