def read_records(file_handle, fmt: str) -> Iterator[Dict[str, str]]:
    """Read records in specified format."""
    if fmt == 'csv':
        yield from read_csv_records(file_handle)
    elif fmt == 'tsv':
        # TSV is CSV with tab delimiter
        reader = csv.DictReader(file_handle, delimiter='\t')
        for row in reader:
            yield OrderedDict(row)
    elif fmt == 'dkvp':
        yield from read_dkvp_records(file_handle)
    elif fmt == 'json':
        yield from read_json_records(file_handle)

def write_dkvp_record(record: Dict[str, str]) -> str:
    """Write a DKVP record."""
