def verb_cat(records, args):
    """Pass through records."""
    return records

def verb_cut(records, args):
    """Select fields."""
    # Parse -f fields_list
    if '-f' not in args:
        return records

    idx = args.index('-f')
    fields_str = args[idx + 1]
    fields = fields_str.split(',')

    for record in records:
        new_record = OrderedDict()
        for field in fields:
            if field in record:
                new_record[field] = record[field]
        yield new_record

def verb_sort(records, args):
    """Sort records by field."""
    records_list = list(records)

    sort_field = None
    reverse = False
    numeric = False

    i = 0
    while i < len(args):
        if args[i] == '-f':
            sort_field = args[i + 1]
            i += 2
        elif args[i] == '-r':
            reverse = True
            i += 1
        elif args[i] == '-n':
            numeric = True
            i += 1
        elif args[i] == '-nr':
            numeric = True
            reverse = True
            i += 1
        else:
            i += 1

    if not sort_field:
        return records_list

    def sort_key(record):
        val = record.get(sort_field, '')
        if numeric:
            try:
                return float(val)
            except (ValueError, TypeError):
                return 0
        return val

    return sorted(records_list, key=sort_key, reverse=reverse)

