import sys
from typing import List, Optional, Iterator
from pathlib import Path

from mlr.formats import (
    Record, read_csv_records, read_tsv_records, read_dkvp_records,
    read_json_records, write_csv_records, write_tsv_records,
    write_dkvp_records, write_json_records, write_pprint_records,
    read_dkvp_record
)
from mlr.verbs import get_verb

def process_pipeline(
    verb: str,
    verb_args: List[str],
    input_format: str,
    output_format: str,
    input_files: Optional[List[str]] = None,
    implicit_csv_header: bool = False,
    implicit_tsv_header: bool = False,
    jknquoteint: bool = False,
    jquoteall: bool = False,
    jflatsep: str = '_',
):
    """Process data through a Miller verb."""

    # Get the verb handler
    verb_handler = get_verb(verb)
    if verb_handler is None:
        print(f"mlr: Unknown verb: {verb}", file=sys.stderr)
        return

    # Read input data
    records = []
    headers = None

    if input_files:
        for filepath in input_files:
            with open(filepath, 'r') as f:
                records.extend(_read_format(
                    f, input_format,
                    implicit_csv_header, implicit_tsv_header
                ))
    else:
        records.extend(_read_format(
            sys.stdin, input_format,
            implicit_csv_header, implicit_tsv_header
        ))

    # Get headers from first record if available
    if records:
        headers = list(records[0].keys())

    # Process through verb
    processed_records = verb_handler(iter(records), verb_args)

    # Write output
    _write_format(processed_records, output_format, sys.stdout, headers)

def _read_format(file_handle, fmt: str, implicit_csv: bool = False, implicit_tsv: bool = False) -> List[Record]:
    """Read records in specified format."""
    records = []

    if fmt == 'csv':
        for headers, record in read_csv_records(file_handle, implicit_csv):
            records.append(record)
    elif fmt == 'tsv':
        for headers, record in read_tsv_records(file_handle, implicit_tsv):
            records.append(record)
    elif fmt == 'dkvp':
        for headers, record in read_dkvp_records(file_handle):
            records.append(record)
    elif fmt == 'json':
        for headers, record in read_json_records(file_handle):
            records.append(record)

    return records

def _write_format(records: Iterator[Record], fmt: str, file_handle, headers=None):
    """Write records in specified format."""
    if fmt == 'csv':
        write_csv_records(records, file_handle, headers)
    elif fmt == 'tsv':
        write_tsv_records(records, file_handle, headers)
    elif fmt == 'dkvp':
        write_dkvp_records(records, file_handle, headers)
    elif fmt == 'json':
        write_json_records(records, file_handle, headers)
    elif fmt == 'pprint':
        write_pprint_records(records, file_handle, headers)
