                    elif op == '!=':
                        return self._compare_values(left, right) != 0
                    elif op == '<':
                        return self._compare_values(left, right) < 0
                    elif op == '<=':
                        return self._compare_values(left, right) <= 0
                    elif op == '>':
                        return self._compare_values(left, right) > 0
                    elif op == '>=':
                        return self._compare_values(left, right) >= 0

