    def _compare_values(self, left: Any, right: Any) -> int:
        """Compare two values, return -1, 0, or 1."""
        try:
            left_f = float(left)
            right_f = float(right)
            if left_f < right_f:
                return -1
            elif left_f > right_f:
                return 1
            else:
                return 0
        except (ValueError, TypeError):
            left_s = str(left)
            right_s = str(right)
            if left_s < right_s:
                return -1
            elif left_s > right_s:
                return 1
            else:
                return 0

def evaluate_expression(expr: str, record: Record) -> Record:
    """Evaluate an expression and modify record accordingly."""
    evaluator = DSLEvaluator(record)

    # Handle multiple statements separated by semicolons
    statements = expr.split(';')

    for statement in statements:
        statement = statement.strip()
        if statement:
            try:
                evaluator.evaluate(statement)
            except Exception as e:
                pass  # Silently ignore evaluation errors for now

    return evaluator.record

def evaluate_boolean_expression(expr: str, record: Record) -> bool:
    """Evaluate an expression as a boolean."""
    evaluator = DSLEvaluator(record)

    try:
        result = evaluator.evaluate(expr)

        # Convert to boolean
        if isinstance(result, bool):
            return result
        if isinstance(result, (int, float)):
            return result != 0
        if isinstance(result, str):
            return result.lower() not in ('', 'false', '0')

        return bool(result)
    except Exception as e:
        return False
