"""Miller DSL expression evaluator"""

import re
import math
import sys
from typing import Any, Dict, Union
from mlr.formats import Record

# Built-in functions
BUILTIN_FUNCTIONS = {
    'int': lambda x: int(float(str(x))),
    'float': lambda x: float(str(x)),
    'string': lambda x: str(x),
    'strlen': lambda x: len(str(x)),
    'substr': lambda s, start, length: str(s)[int(float(start)):int(float(start)) + int(float(length))],
    'toupper': lambda x: str(x).upper(),
    'tolower': lambda x: str(x).lower(),
    'upper': lambda x: str(x).upper(),
    'lower': lambda x: str(x).lower(),
    'abs': lambda x: abs(float(x)),
    'ceil': lambda x: math.ceil(float(x)),
    'floor': lambda x: math.floor(float(x)),
    'round': lambda x: round(float(x)),
    'sqrt': lambda x: math.sqrt(float(x)),
    'exp': lambda x: math.exp(float(x)),
    'log': lambda x: math.log(float(x)),
    'log10': lambda x: math.log10(float(x)),
    'sin': lambda x: math.sin(float(x)),
    'cos': lambda x: math.cos(float(x)),
    'tan': lambda x: math.tan(float(x)),
}

class DSLEvaluator:
    """Evaluates Miller DSL expressions"""

    def __init__(self, record: Record = None):
        self.record = record or {}
        self.variables = {}

    def evaluate(self, expr: str) -> Any:
        """Evaluate a DSL expression."""
        expr = expr.strip()

        # Handle string literals
        if expr.startswith('"') and expr.endswith('"'):
            return expr[1:-1]

        # Handle numeric literals
        try:
            if '.' in expr:
                return float(expr)
            else:
                return int(expr)
        except ValueError:
            pass

        # Handle field references
        if expr.startswith('$'):
            field_name = expr[1:]
            return self.record.get(field_name, '')

        # Handle boolean literals
        if expr.lower() == 'true':
            return True
        if expr.lower() == 'false':
            return False

        # Handle variables
        if expr.startswith('@'):
            var_name = expr[1:]
            return self.variables.get(var_name, '')

        # Handle function calls
        if '(' in expr and ')' in expr:
            return self._evaluate_function(expr)

        # Handle binary operations
        return self._evaluate_binary_op(expr)

    def _evaluate_function(self, expr: str) -> Any:
        """Evaluate function calls."""
        match = re.match(r'(\w+)\((.*)\)', expr)
        if not match:
            return expr

        func_name = match.group(1)
        args_str = match.group(2)

        # Parse arguments
        args = self._parse_args(args_str)
        evaluated_args = [self.evaluate(arg.strip()) for arg in args]

        if func_name in BUILTIN_FUNCTIONS:
            try:
                return BUILTIN_FUNCTIONS[func_name](*evaluated_args)
            except Exception as e:
                raise Exception(f"Error in function {func_name}: {e}")

        return expr

    def _parse_args(self, args_str: str) -> list:
        """Parse function arguments, respecting nested structures."""
        args = []
        current = ""
        depth = 0
        in_string = False

        for char in args_str:
            if char == '"':
                in_string = not in_string
                current += char
            elif not in_string:
                if char in '([{':
                    depth += 1
                    current += char
                elif char in ')]}':
                    depth -= 1
                    current += char
                elif char == ',' and depth == 0:
                    args.append(current)
                    current = ""
                else:
                    current += char
            else:
                current += char

        if current:
            args.append(current)

        return args

