        """Evaluate binary operations."""
        # Handle assignment (=)
        if ' = ' in expr and not any(op in expr for op in ['==', '!=', '<=', '>=', '=~', '!~']):
            parts = expr.split(' = ', 1)
            if len(parts) == 2:
