                    elif op == '!=':
                        return self._compare_values(left, right) != 0
                    elif op == '<':
                        return self._compare_values(left, right) < 0
                    elif op == '<=':
                        return self._compare_values(left, right) <= 0
                    elif op == '>':
                        return self._compare_values(left, right) > 0
                    elif op == '>=':
                        return self._compare_values(left, right) >= 0

        # Handle arithmetic operators
        for op in ['+', '-', '*', '/', '%']:
            if f' {op} ' in expr:
                parts = expr.rsplit(f' {op} ', 1)
                if len(parts) == 2:
                    try:
