"""Data format handling for Miller"""

import csv
import json
from collections import OrderedDict
from typing import Dict, Iterator, List, Tuple, Any, Optional
import io

def determine_input_format(args) -> str:
    """Determine input format from arguments."""
    if args.icsv or args.csv:
        return 'csv'
    if args.itsv or args.tsv:
        return 'tsv'
    if args.idkvp or args.dkvp:
        return 'dkvp'
    if args.ijson or args.json:
        return 'json'
    if args.ipprint or args.pprint:
        return 'pprint'
    return 'dkvp'  # Default

def determine_output_format(args) -> str:
    """Determine output format from arguments."""
    if args.ocsv or args.csv:
        return 'csv'
    if args.otsv or args.tsv:
        return 'tsv'
    if args.odkvp or args.dkvp:
        return 'dkvp'
    if args.ojson or args.json:
        return 'json'
    if args.opprint or args.pprint:
        return 'pprint'
    return 'dkvp'  # Default

class Record(OrderedDict):
    """A record is an ordered dictionary"""
    pass

def read_dkvp_record(line: str) -> Record:
    """Parse a DKVP (key=value,key=value) record."""
    record = Record()
    line = line.rstrip('\n\r')
    if not line:
        return record

    # Split by comma but respect escaping
    pairs = []
    current = ""
    i = 0
    while i < len(line):
        if line[i] == '\\' and i + 1 < len(line):
            current += line[i:i+2]
            i += 2
        elif line[i] == ',':
            pairs.append(current)
            current = ""
            i += 1
        else:
            current += line[i]
            i += 1
    if current:
        pairs.append(current)

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            record[key] = value

    return record

def write_dkvp_record(record: Record) -> str:
    """Write a DKVP record."""
    pairs = []
    for k, v in record.items():
        # Simple escaping for now
        v_str = str(v)
        pairs.append(f"{k}={v_str}")
    return ','.join(pairs)

def read_csv_records(file_handle, implicit_header=False) -> Iterator[Tuple[List[str], Record]]:
    """Read CSV records."""
    reader = csv.reader(file_handle)
    headers = None

    for row in reader:
        if headers is None:
            if implicit_header:
                headers = [str(i+1) for i in range(len(row))]
                record = Record(zip(headers, row))
                yield headers, record
            else:
                headers = row
            continue

        if len(row) < len(headers):
            # Pad with empty strings
            row.extend([''] * (len(headers) - len(row)))
        elif len(row) > len(headers):
            # Add numeric fields for extras
            extra_headers = [str(i) for i in range(len(headers), len(row))]
            headers.extend(extra_headers)

        record = Record(zip(headers, row))
        yield headers, record

def read_tsv_records(file_handle, implicit_header=False) -> Iterator[Tuple[List[str], Record]]:
    """Read TSV records."""
    reader = csv.reader(file_handle, delimiter='\t')
    headers = None

    for row in reader:
        if headers is None:
            if implicit_header:
                headers = [str(i+1) for i in range(len(row))]
                record = Record(zip(headers, row))
                yield headers, record
            else:
                headers = row
            continue

        if len(row) < len(headers):
            row.extend([''] * (len(headers) - len(row)))
        elif len(row) > len(headers):
            extra_headers = [str(i) for i in range(len(headers), len(row))]
            headers.extend(extra_headers)

        record = Record(zip(headers, row))
        yield headers, record

def read_json_records(file_handle) -> Iterator[Tuple[List[str], Record]]:
    """Read JSON lines records."""
    headers = None
    for line in file_handle:
        line = line.strip()
        if not line:
            continue

        try:
            obj = json.loads(line)
            if isinstance(obj, dict):
                if headers is None:
                    headers = list(obj.keys())
                record = Record(obj)
                yield headers or list(record.keys()), record
        except json.JSONDecodeError:
            continue

def read_dkvp_records(file_handle) -> Iterator[Tuple[List[str], Record]]:
    """Read DKVP records."""
    headers = None
    for line in file_handle:
        record = read_dkvp_record(line)
        if not record:
            continue

        if headers is None:
            headers = list(record.keys())
        yield headers, record

def write_csv_records(records: Iterator[Record], file_handle, headers=None):
    """Write CSV records."""
    record_list = list(records)
    if not record_list:
        return

    if headers is None:
        headers = list(record_list[0].keys())

    writer = csv.DictWriter(file_handle, fieldnames=headers, extrasaction='ignore', restval='')
    writer.writeheader()
    for record in record_list:
        # Create a dict with all fields, using empty string for missing ones
        row_dict = {k: record.get(k, '') for k in headers}
        writer.writerow(row_dict)

def write_tsv_records(records: Iterator[Record], file_handle, headers=None):
    """Write TSV records."""
    record_list = list(records)
    if not record_list:
        return

    if headers is None:
        headers = list(record_list[0].keys())

    writer = csv.DictWriter(file_handle, fieldnames=headers, delimiter='\t', extrasaction='ignore', restval='')
    writer.writeheader()
    for record in record_list:
        row_dict = {k: record.get(k, '') for k in headers}
        writer.writerow(row_dict)

def write_dkvp_records(records: Iterator[Record], file_handle, headers=None):
    """Write DKVP records."""
    for record in records:
        file_handle.write(write_dkvp_record(record) + '\n')

def write_json_records(records: Iterator[Record], file_handle, headers=None):
    """Write JSON lines records."""
    for record in records:
        file_handle.write(json.dumps(dict(record)) + '\n')

def write_pprint_records(records: Iterator[Record], file_handle, headers=None):
    """Write PPRINT (pretty-print) records."""
    record_list = list(records)
    if not record_list:
        return

    if headers is None:
        headers = list(record_list[0].keys())

    # Calculate column widths
    col_widths = {}
    for header in headers:
        col_widths[header] = len(str(header))

    for record in record_list:
        for header in headers:
            val = str(record.get(header, ''))
            col_widths[header] = max(col_widths[header], len(val))

    # Write header
    header_parts = []
    for header in headers:
        header_parts.append(str(header).ljust(col_widths[header]))
    file_handle.write(' '.join(header_parts) + '\n')

    # Write records
    for record in record_list:
        row_parts = []
        for header in headers:
            val = str(record.get(header, ''))
            row_parts.append(val.ljust(col_widths[header]))
        file_handle.write(' '.join(row_parts) + '\n')
