    out_headers = list(group_by) + ['count']

    def process():
        if group_by:
            counts = defaultdict(int)
            for record in all_records:
                key = tuple(record.get(f, '') for f in group_by)
                counts[key] += 1

            for key, count in counts.items():
                result = Record()
                for i, field in enumerate(group_by):
                    result[field] = key[i]
                result['count'] = count
                yield result
