    while i < len(args):
        if args[i] == '-r':
            # Parse rename specification
            pairs = args[i + 1].split(',')
            for pair in pairs:
                if '=' in pair:
                    old, new = pair.split('=', 1)
                    renames[old] = new
            i += 2
        else:
            i += 1

    out_headers = [renames.get(h, h) for h in headers] if headers else []

    def process():
        for record in records:
            new_record = Record()
            for key, value in record.items():
                new_key = renames.get(key, key)
                new_record[new_key] = value
            yield new_record

