        if args[i] == '-f':
            fields = args[i + 1].split(',')
            i += 2
        else:
            i += 1

    # Build output headers
    out_headers = []
    if fields:
        # First add specified fields in order
        for field in fields:
            if field in headers:
                out_headers.append(field)
        # Then add remaining fields
        for field in headers:
            if field not in out_headers:
                out_headers.append(field)
    else:
        out_headers = list(headers) if headers else []

    def process():
        for record in records:
            new_record = Record()

            # First add specified fields in order
            if fields:
                for field in fields:
                    if field in record:
                        new_record[field] = record[field]

                # Then add remaining fields
                for key, value in record.items():
                    if key not in new_record:
                        new_record[key] = value
            else:
                new_record = record

            yield new_record

    return process(), out_headers

def verb_top(records: Iterator[Record], args: List[str], headers: List[str] = None) -> Tuple[Iterator[Record], List[str]]:
    """Get top records by field."""
    field = None
    count = 10

    i = 0
    while i < len(args):
        if args[i] == '-f':
            field = args[i + 1]
            i += 2
        elif args[i] == '-n':
            count = int(args[i + 1])
            i += 2
        else:
            i += 1

    all_records = list(records)

    def process():
        if not field:
            # Just return first N records
            for j, record in enumerate(all_records):
                if j < count:
                    yield record
                else:
                    break
            return

        try:
            sorted_records = sorted(
                all_records,
                key=lambda r: float(r.get(field, 0)),
                reverse=True
            )
        except (ValueError, TypeError):
            sorted_records = sorted(
                all_records,
                key=lambda r: str(r.get(field, '')),
                reverse=True
            )

        for record in sorted_records[:count]:
            yield record

    return process(), headers

def verb_nothing(records: Iterator[Record], args: List[str], headers: List[str] = None) -> Tuple[Iterator[Record], List[str]]:
    """Output nothing."""
    def process():
        for _ in records:
            pass
        return
        yield  # Make it a generator

    return process(), headers

def verb_group_by(records: Iterator[Record], args: List[str], headers: List[str] = None) -> Tuple[Iterator[Record], List[str]]:
    """Group records by fields."""
    group_by = []

    if args:
        group_by = args[0].split(',')

    all_records = list(records)
    groups = defaultdict(list)

    for record in all_records:
        key = tuple(record.get(f, '') for f in group_by)
        groups[key].append(record)

    def process():
        for records_in_group in groups.values():
            for record in records_in_group:
                yield record

    return process(), headers

def verb_join(records: Iterator[Record], args: List[str], headers: List[str] = None) -> Tuple[Iterator[Record], List[str]]:
    """Join records (simplified)."""
    def process():
        for record in records:
            yield record

    return process(), headers

def verb_step(records: Iterator[Record], args: List[str], headers: List[str] = None) -> Tuple[Iterator[Record], List[str]]:
    """Compute step functions."""
    def process():
        for record in records:
            yield record

