    def _evaluate_function(self, expr: str) -> Any:
        """Evaluate function calls."""
        match = re.match(r'(\w+)\((.*)\)$', expr)
        if not match:
            return expr

        func_name = match.group(1)
        args_str = match.group(2)

        # Parse arguments
        args = self._parse_args(args_str)
        evaluated_args = [self.evaluate(arg.strip()) for arg in args]

        if func_name in BUILTIN_FUNCTIONS:
            try:
                return BUILTIN_FUNCTIONS[func_name](*evaluated_args)
            except Exception as e:
                raise Exception(f"Error in function {func_name}: {e}")

        return expr

    def _parse_args(self, args_str: str) -> list:
        """Parse function arguments, respecting nested structures."""
        args = []
        current = ""
        depth = 0
        in_string = False

        for char in args_str:
            if char == '"':
                in_string = not in_string
                current += char
            elif not in_string:
                if char in '([{':
                    depth += 1
                    current += char
                elif char in ')]}':
                    depth -= 1
                    current += char
                elif char == ',' and depth == 0:
                    args.append(current)
                    current = ""
                else:
                    current += char
            else:
                current += char

        if current:
            args.append(current)

        return args

def evaluate_expression(expr: str, record: Record) -> Record:
    """Evaluate an expression and modify record accordingly."""
    evaluator = DSLEvaluator(record)

    # Handle multiple statements separated by semicolons
    statements = expr.split(';')

    for statement in statements:
        statement = statement.strip()
        if statement:
            try:
                evaluator.evaluate(statement)
            except Exception as e:
                pass  # Silently ignore evaluation errors for now

    return evaluator.record

def evaluate_boolean_expression(expr: str, record: Record) -> bool:
    """Evaluate an expression as a boolean."""
    evaluator = DSLEvaluator(record)

    try:
        result = evaluator.evaluate(expr)

        # Convert to boolean
        if isinstance(result, bool):
            return result
        if isinstance(result, (int, float)):
            return result != 0
        if isinstance(result, str):
            return result.lower() not in ('', 'false', '0')

        return bool(result)
    except Exception as e:
        return False
