"""Main processing pipeline for Miller"""

import sys
from typing import List, Optional, Iterator, Tuple
from pathlib import Path

from mlr.formats import (
    Record, read_csv_records, read_tsv_records, read_dkvp_records,
    read_json_records, write_csv_records, write_tsv_records,
    write_dkvp_records, write_json_records, write_pprint_records,
    read_dkvp_record
)
from mlr.verbs import get_verb

def process_pipeline(
    verb_pipeline: List[Tuple[str, List[str]]],
    input_format: str,
    output_format: str,
    input_files: Optional[List[str]] = None,
    implicit_csv_header: bool = False,
    implicit_tsv_header: bool = False,
    jknquoteint: bool = False,
    jquoteall: bool = False,
    jflatsep: str = '_',
):
    """Process data through a pipeline of Miller verbs."""

    # Read input data
    records, headers = _read_format(
        input_files, input_format,
        implicit_csv_header, implicit_tsv_header
    )

    # Process through verb pipeline
    for verb_name, verb_args in verb_pipeline:
        verb_handler = get_verb(verb_name)
        if verb_handler is None:
            print(f"mlr: Unknown verb: {verb_name}", file=sys.stderr)
            return

        records_iter, headers = verb_handler(iter(records), verb_args, headers)
        records = list(records_iter)

    # Write output
    _write_format(iter(records), output_format, sys.stdout, headers)

def _read_format(input_files: Optional[List[str]], fmt: str, implicit_csv: bool = False, implicit_tsv: bool = False) -> Tuple[List[Record], List[str]]:
    """Read records in specified format."""
    records = []
    headers = None

    if input_files:
        for filepath in input_files:
            with open(filepath, 'r') as f:
                file_records, file_headers = _read_from_handle(f, fmt, implicit_csv, implicit_tsv)
                records.extend(file_records)
                if headers is None:
                    headers = file_headers
    else:
        records, headers = _read_from_handle(sys.stdin, fmt, implicit_csv, implicit_tsv)

    return records, headers or []

def _read_from_handle(file_handle, fmt: str, implicit_csv: bool = False, implicit_tsv: bool = False) -> Tuple[List[Record], List[str]]:
    """Read records from a file handle in specified format."""
    records = []
    headers = None

    if fmt == 'csv':
        for file_headers, record in read_csv_records(file_handle, implicit_csv):
            records.append(record)
            if headers is None:
                headers = file_headers
    elif fmt == 'tsv':
        for file_headers, record in read_tsv_records(file_handle, implicit_tsv):
            records.append(record)
            if headers is None:
                headers = file_headers
    elif fmt == 'dkvp':
        for file_headers, record in read_dkvp_records(file_handle):
            records.append(record)
            if headers is None:
                headers = file_headers
    elif fmt == 'json':
        for file_headers, record in read_json_records(file_handle):
            records.append(record)
            if headers is None:
                headers = file_headers

    return records, headers or []

def _write_format(records: Iterator[Record], fmt: str, file_handle, headers=None):
    """Write records in specified format."""
    if fmt == 'csv':
        write_csv_records(records, file_handle, headers)
    elif fmt == 'tsv':
        write_tsv_records(records, file_handle, headers)
    elif fmt == 'dkvp':
        write_dkvp_records(records, file_handle, headers)
    elif fmt == 'json':
        write_json_records(records, file_handle, headers)
    elif fmt == 'pprint':
        write_pprint_records(records, file_handle, headers)
