"""Miller DSL expression evaluator"""

import re
import math
import sys
from typing import Any, Dict, Union, Tuple
from mlr.formats import Record

# Built-in functions
BUILTIN_FUNCTIONS = {
    'int': lambda x: int(float(str(x))),
    'float': lambda x: float(str(x)),
    'string': lambda x: str(x),
    'strlen': lambda x: len(str(x)),
    'substr': lambda s, start, length: str(s)[int(float(start)):int(float(start)) + int(float(length))],
    'toupper': lambda x: str(x).upper(),
    'tolower': lambda x: str(x).lower(),
    'upper': lambda x: str(x).upper(),
    'lower': lambda x: str(x).lower(),
    'abs': lambda x: abs(float(x)),
    'ceil': lambda x: math.ceil(float(x)),
    'floor': lambda x: math.floor(float(x)),
    'round': lambda x: round(float(x)),
    'sqrt': lambda x: math.sqrt(float(x)),
    'exp': lambda x: math.exp(float(x)),
    'log': lambda x: math.log(float(x)),
    'log10': lambda x: math.log10(float(x)),
    'sin': lambda x: math.sin(float(x)),
    'cos': lambda x: math.cos(float(x)),
    'tan': lambda x: math.tan(float(x)),
    'max': lambda *args: max(float(a) for a in args),
    'min': lambda *args: min(float(a) for a in args),
    'typeof': lambda x: type(x).__name__,
}

def _try_numeric_convert(val: Any) -> Union[float, str]:
    """Try to convert a value to numeric if possible."""
    if isinstance(val, (int, float)):
        return val
    try:
        # Try int first
        return int(str(val))
    except (ValueError, TypeError):
        try:
            # Then try float
            return float(str(val))
        except (ValueError, TypeError):
            # Keep as string
            return str(val)

def _compare_values(left: Any, right: Any) -> int:
    """Compare two values, return -1, 0, or 1."""
    # Try numeric comparison first
    left_conv = _try_numeric_convert(left)
    right_conv = _try_numeric_convert(right)

    # If both are numeric, do numeric comparison
    if isinstance(left_conv, (int, float)) and isinstance(right_conv, (int, float)):
        if left_conv < right_conv:
            return -1
        elif left_conv > right_conv:
            return 1
        else:
            return 0

    # String comparison
    left_s = str(left)
    right_s = str(right)
    if left_s < right_s:
        return -1
    elif left_s > right_s:
        return 1
    else:
        return 0

class DSLEvaluator:
    """Evaluates Miller DSL expressions"""

    def __init__(self, record: Record = None):
        self.record = record or {}
        self.variables = {}

    def evaluate(self, expr: str) -> Any:
        """Evaluate a DSL expression."""
        expr = expr.strip()

        # Handle empty
        if not expr:
            return ''

        # Handle string literals
        if expr.startswith('"') and expr.endswith('"'):
            return expr[1:-1]

        # Handle boolean literals  
        if expr.lower() == 'true':
            return True
        if expr.lower() == 'false':
            return False

        # Check for assignment FIRST before any operators, to avoid side effects
        result = self._try_assignment(expr)
        if result is not None:
            return result

        # Check for comparison operators (they have lower precedence than arithmetic)
        result = self._try_comparison_op(expr)
        if result is not None:
            return result

        # Check for arithmetic
        result = self._try_arithmetic_op(expr)
        if result is not None:
            return result

        # Handle function calls
        if '(' in expr and ')' in expr:
            return self._evaluate_function(expr)

        # Handle numeric literals
        try:
            if '.' in expr:
                return float(expr)
            else:
                return int(expr)
        except ValueError:
            pass

        # Handle field references
        if expr.startswith('$'):
            field_name = expr[1:]
            return self.record.get(field_name, '')

        # Handle variables
        if expr.startswith('@'):
            var_name = expr[1:]
            return self.variables.get(var_name, '')

        return expr

    def _try_comparison_op(self, expr: str) -> Any:
        """Try to evaluate as a comparison operation."""
        # Check for comparison operators (order matters - check longer ones first)
        for op in ['==', '!=', '<=', '>=', '<', '>']:
            if f' {op} ' not in expr:
                continue

            # Find the rightmost occurrence to handle chained operations correctly
            idx = expr.rfind(f' {op} ')
            if idx == -1:
                continue

            left_expr = expr[:idx]
            right_expr = expr[idx+len(op)+2:]

            # Skip if this operator is inside a function call or string
            if not self._is_operator_outside_parens(expr, idx):
                continue

            # Skip if this is part of an assignment like '$x <= 5'
            if ' = ' in left_expr:
                continue

            left = self.evaluate(left_expr)
            right = self.evaluate(right_expr)

            cmp_result = _compare_values(left, right)

            if op == '==':
                return cmp_result == 0
            elif op == '!=':
                return cmp_result != 0
            elif op == '<':
                return cmp_result < 0
            elif op == '<=':
                return cmp_result <= 0
            elif op == '>':
                return cmp_result > 0
            elif op == '>=':
                return cmp_result >= 0

        return None

    def _try_arithmetic_op(self, expr: str) -> Any:
        """Try to evaluate as an arithmetic operation."""
        # Skip if this looks like an assignment
        if ' = ' in expr and not any(op in expr for op in ['==', '!=', '<=', '>=', '=~', '!~']):
            return None

        # Check for arithmetic operators (order matters - lower precedence first)
        for op in ['+', '-', '*', '/', '%']:
            if f' {op} ' not in expr:
                continue

            # Find the rightmost occurrence
            idx = expr.rfind(f' {op} ')
            if idx == -1:
                continue

            # Skip if this operator is inside a function call or string
            if not self._is_operator_outside_parens(expr, idx):
                continue

            left_expr = expr[:idx]
            right_expr = expr[idx+len(op)+2:]

            try:
                left = float(self.evaluate(left_expr))
                right = float(self.evaluate(right_expr))

                if op == '+':
                    return left + right
                elif op == '-':
                    return left - right
                elif op == '*':
                    return left * right
                elif op == '/':
                    return left / right if right != 0 else 0
                elif op == '%':
                    return left % right if right != 0 else 0
            except (ValueError, TypeError):
                pass

        return None

    def _try_assignment(self, expr: str) -> Any:
        """Try to evaluate as an assignment."""
        if ' = ' in expr and not any(op in expr for op in ['==', '!=', '<=', '>=', '=~', '!~']):
            idx = expr.find(' = ')
            if idx != -1 and self._is_operator_outside_parens(expr, idx):
                left = expr[:idx].strip()
                right = self.evaluate(expr[idx+3:])

                if left.startswith('$'):
                    field_name = left[1:]
                    self.record[field_name] = right
                elif left.startswith('@'):
                    var_name = left[1:]
                    self.variables[var_name] = right

                return right

        return None

    def _is_operator_outside_parens(self, expr: str, idx: int) -> bool:
        """Check if operator at position idx is outside of parentheses."""
        paren_depth = 0
        in_string = False
        for i in range(idx):
            if expr[i] == '"' and (i == 0 or expr[i-1] != '\\'):
                in_string = not in_string
            elif not in_string:
                if expr[i] == '(':
                    paren_depth += 1
                elif expr[i] == ')':
                    paren_depth -= 1
        return paren_depth == 0

    def _evaluate_function(self, expr: str) -> Any:
        """Evaluate function calls."""
        match = re.match(r'(\w+)\((.*)\)$', expr)
        if not match:
            return expr

        func_name = match.group(1)
        args_str = match.group(2)

        # Parse arguments
        args = self._parse_args(args_str)
        evaluated_args = [self.evaluate(arg.strip()) for arg in args]

        if func_name in BUILTIN_FUNCTIONS:
            try:
                return BUILTIN_FUNCTIONS[func_name](*evaluated_args)
            except Exception as e:
                raise Exception(f"Error in function {func_name}: {e}")

        return expr

    def _parse_args(self, args_str: str) -> list:
        """Parse function arguments, respecting nested structures."""
        args = []
        current = ""
        depth = 0
        in_string = False

        for char in args_str:
            if char == '"':
                in_string = not in_string
                current += char
            elif not in_string:
                if char in '([{':
                    depth += 1
                    current += char
                elif char in ')]}':
                    depth -= 1
                    current += char
                elif char == ',' and depth == 0:
                    args.append(current)
                    current = ""
                else:
                    current += char
            else:
                current += char

        if current:
            args.append(current)

        return args

def evaluate_expression(expr: str, record: Record) -> Record:
    """Evaluate an expression and modify record accordingly."""
    evaluator = DSLEvaluator(record)

    # Handle multiple statements separated by semicolons
    statements = expr.split(';')

    for statement in statements:
        statement = statement.strip()
        if statement:
            try:
                evaluator.evaluate(statement)
            except Exception as e:
                pass  # Silently ignore evaluation errors for now

    return evaluator.record

def evaluate_boolean_expression(expr: str, record: Record) -> bool:
    """Evaluate an expression as a boolean."""
    evaluator = DSLEvaluator(record)

    try:
        result = evaluator.evaluate(expr)

        # Convert to boolean
        if isinstance(result, bool):
            return result
        if isinstance(result, (int, float)):
            return result != 0
        if isinstance(result, str):
            return result.lower() not in ('', 'false', '0')

        return bool(result)
    except Exception as e:
        return False
