    """Regularize records (ensure all records have same fields)."""
    # Collect all records to see all possible fields
    all_records = list(records)
    all_fields = set()

    for record in all_records:
        all_fields.update(record.keys())

    out_headers = list(headers) if headers else sorted(all_fields)

    def process():
        for record in all_records:
            new_record = Record()
            for field in out_headers:
                new_record[field] = record.get(field, '')
            yield new_record

    return process(), out_headers

