    """Merge multiple fields into one."""
    separator = ','
    fields = []
    new_field_name = 'merged'

    i = 0
    while i < len(args):
        if args[i] == '-i':
            separator = args[i + 1]
            i += 2
        elif args[i] == '-o':
            new_field_name = args[i + 1]
            i += 2
        elif args[i] == '-f':
            fields = args[i + 1].split(',')
            i += 2
        else:
            i += 1

    out_headers = list(headers) if headers else []
    if new_field_name not in out_headers and fields:
        out_headers.append(new_field_name)

    def process():
        for record in records:
            values = []
            for field in fields:
                if field in record:
                    values.append(str(record[field]))
            if values:
                record[new_field_name] = separator.join(values)
            yield record

